begin;
with j as (select * from jsonb_to_recordset($law7d0011$[{"code_id":"BK_RF","article_number":"23","version_date":"1998-07-31","article_text":"1. Код классификации источников финансирования дефицитов бюджетов состоит из:\n\n1)  кода главного администратора источников финансирования дефицитов бюджетов;\n\n2)  кода группы,  подгруппы,  статьи и вида источника финансирования дефицитов бюджетов;\n\n3)  (Подпункт утратил силу - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n2. (Пункт утратил силу - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n3. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами источников финансирования дефицитов бюджетов являются:\n\n1)  источники внутреннего финансирования дефицитов бюджетов:\n\nгосударственные (муниципальные)  ценные бумаги,  номинальная стоимость которых указана в валюте Российской Федерации;\n\nкредиты кредитных организаций в валюте Российской Федерации;\n\nбюджетные кредиты из других бюджетов бюджетной системы Российской Федерации; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты международных финансовых организаций в валюте Российской Федерации;\n\nкредиты иностранных банков в валюте Российской Федерации; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nизменение остатков средств на счетах по учету средств бюджета;\n\nиные источники внутреннего финансирования дефицитов бюджетов;\n\n2)  источники внешнего финансирования дефицитов бюджетов:\n\nгосударственные ценные бумаги,  номинальная стоимость которых указана в иностранной валюте;\n\nкредиты иностранных государств,  включая целевые иностранные кредиты,  международных финансовых организаций,  иных субъектов международного права,  иностранных юридических лиц в иностранной валюте; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nкредиты кредитных организаций в иностранной валюте;\n\nбюджетные кредиты в иностранной валюте,  предоставленные Российской Федерацией в рамках использования целевых иностранных кредитов; (Дополнение абзацем - Федеральный закон от 02.08.2019 № 278-ФЗ)\n\nиные источники внешнего финансирования дефицитов бюджетов.\n\n4. Перечень статей источников финансирования дефицитов бюджетов утверждается законом (решением)  о соответствующем бюджете при утверждении источников финансирования дефицита бюджета. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n5. Министерство финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса утверждает: (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\nобщие требования к порядку формирования перечня кодов статей и видов источников финансирования дефицитов бюджетов;\n\nперечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы государственной власти Российской Федерации,  органы управления государственными внебюджетными фондами Российской Федерации и (или)  находящиеся в их ведении казенные учреждения.\n\nВнесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзаце третьем настоящего пункта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых источников финансирования дефицит\n\nприкладные научные исследования в области общегосударственных вопросов;\n\nдругие общегосударственные вопросы;\n\n2)  национальная оборона:\n\nВооруженные Силы Российской Федерации;\n\nмодернизация Вооруженных Сил Российской Федерации и воинских формирований;\n\nмобилизационная и вневойсковая подготовка;\n\nмобилизационная подготовка экономики;\n\nподготовка и участие в обеспечении коллективной безопасности и миротворческой деятельности;\n\nядерно-оружейный комплекс;\n\nреализация международных обязательств в сфере военно-технического сотрудничества;\n\nприкладные научные исследования в области национальной обороны;\n\nдругие вопросы в области национальной обороны;\n\n3)  национальная безопасность и правоохранительная деятельность:\n\nорганы прокуратуры и следствия; (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nорганы внутренних дел;\n\nвойска национальной гвардии Российской Федерации; (В редакции Федерального закона от 03.07.2016 № 229-ФЗ)\n\nорганы юстиции;\n\nсистема исполнения наказаний;\n\nорганы безопасности;\n\nорганы пограничной службы;\n\nабзац; (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nзащита населения и территории от чрезвычайных ситуаций природного и техногенного характера,  пожарная безопасность; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nгражданская оборона; (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nмиграционная политика;\n\nмодернизация войск национальной гвардии Российской Федерации,  спасательных воинских формирований федерального органа исполнительной власти,  уполномоченного на решение задач в области гражданской обороны,  а также правоохранительных и иных органов; (В редакции федеральных законов от 27.07.2010 № 223-ФЗ; от 03.07.2016 № 229-ФЗ)\n\nприкладные научные исследования в области национальной безопасности и правоохранительной деятельности;\n\nдругие вопросы в области национальной безопасности и правоохранительной деятельности;\n\n4)  национальная экономика:\n\nобщеэкономические вопросы;\n\nтопливно-энергетический комплекс;\n\nисследование и использование космического пространства;\n\nвоспроизводство минерально-сырьевой базы;\n\nсельское хозяйство и рыболовство;\n\nводное хозяйство; (В редакции Федерального закона от 14.07.2008 № 118-ФЗ)\n\nлесное хозяйство;\n\nтранспорт;\n\nдорожное хозяйство (дорожные фонды) ; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nсвязь и информатика;\n\nприкладные научные исследования в области национальной экономики;\n\nдругие вопросы в области национальной экономики;\n\n5)  жилищно-коммунальное хозяйство:\n\nжилищное хозяйство;\n\nкоммунальное хозяйство;\n\nблагоустройство;\n\nприкладные научные исследования в области жилищно-коммунального хозяйства;\n\nдругие вопросы в области жилищно-коммунального хозяйства;\n\n6)  охрана окружающей среды:\n\nэкологический контроль;\n\nсбор,  удаление отходов и очистка сточных вод;\n\nохрана объектов растительного и животного мира и среды их обитания;\n\nприкладные научные исследования в области охраны окружающей среды;\n\nдругие вопросы в области охраны окружающей среды;\n\n7)  образование:\n\nдошкольное образование;\n\nобщее образование;\n\nдополнительное образование детей; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nсреднее профессиональное образование;\n\nпрофессиональная подготовка,  переподготовка и повышение квалификации;\n\nвысшее образование; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nмолодежная политика; (В редакции Федерального закона от 14.12.2015 № 381-ФЗ)\n\nприкладные научные исследования в области образования;\n\nдругие вопросы в области образования;\n\n8)  культура,  кинематография: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nкинематография;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области культуры,  кинематографии; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n9)  здравоохранение: (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nстационарная медицинская помощь;\n\nамбулаторная помощь;\n\nмедицинская помощь в дневных стационарах всех типов;\n\nскорая медицинская помощь;\n\nсанаторно-оздоровительная помощь;\n\nзаготовка,  переработка,  хранение и обеспечение безопасности донорской крови и ее компонентов;\n\nсанитарно-эпидемиологическое благополучие;\n\nабзац; (Утратил силу - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\nприкладные научные исследования в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\nдругие вопросы в области здравоохранения; (В редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n10)  социальная политика:\n\nпенсионное обеспечение;\n\nсоциальное обслуживание населения;\n\nсоциальное обеспечение населения;\n\nохрана семьи и детства;\n\nприкладные научные исследования в области социальной политики;\n\nдругие вопросы в области социальной политики;\n\n11)  физическая культура и спорт:\n\nфизическая культура;\n\nмассовый спорт;\n\nспорт высших достижений;\n\nприкладные научные исследования в области физической культуры и спорта;\n\nдругие вопросы в области физической культуры и спорта;\n\n(Подпункт в редакции Федерального закона от 30.09.2010 № 245-ФЗ)\n\n12)  средства массовой информации:\n\nтелевидение и радиовещание;\n\nпериодическая печать и издательства;\n\nприкладные научные исследования в области средств массовой информации;\n\nдругие вопросы в области средств массовой информации;\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n13)  обслуживание государственного (муниципального)  долга: (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внутреннего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nобслуживание государственного (муниципального)  внешнего долга; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n14)  межбюджетные трансферты общего характера бюджетам бюджетной системы Российской Федерации: (В редакции Федерального закона от 04.10.2014 № 283-ФЗ)\n\nдотации на выравнивание бюджетной обеспеченности субъектов Российской Федерации и муниципальных образований;\n\nиные дотации;\n\nпрочие межбюджетные трансферты общего характера.\n\n(Дополнение подпунктом - Федеральный закон от 30.09.2010 № 245-ФЗ)\n\n4. Перечень разделов,  подразделов,  целевых статей (государственных (муниципальных)  программ и непрограммных направлений деятельности) ,  групп (групп и подгрупп)  видов расходов бюджета утверждается в составе ведомственной структуры расходов бюджета законом (решением)  о бюджете либо в установленных настоящим Кодексом случаях сводной бюджетной росписью соответствующего бюджета. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nЦелевые статьи расходов бюджетов формируются в соответствии с государственными (муниципальными)  программами,  не включенными в государственные (муниципальные)  программы направлениями деятельности органов государственной власти (государственных органов) ,  органов управления государственными внебюджетными фондами,  органов местного самоуправления,  органов местной администрации,  наиболее значимых учреждений науки,  образования,  культуры и здравоохранения,  указанных в ведомственной структуре расходов бюджета (в целях настоящего Кодекса - непрограммные направления деятельности) ,  и (или)  расходными обязательствами,  подлежащими исполнению за счет средств соответствующих бюджетов. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\nКаждому публичному нормативному обязательству,  межбюджетному трансферту,  инициативному проекту,  предусмотренному статьей 261 Федерального закона от 6 октября 2003 года № 131-ФЗ \"Об общих принципах организации местного самоуправления в Российской Федерации\",  поддержанному органами местного самоуправления (далее - инициативный проект) ,  присваиваются уникальные коды классификации расходов бюджетов. (В редакции федеральных законов от 30.12.2008 № 310-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 26.07.2019 № 199-ФЗ,  от 20.07.2020 № 216-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов устанавливаются с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  если иное не установлено настоящим Кодексом.  (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов,  финансовое обеспечение которых осуществляется за счет межбюджетных субсидий,  субвенций и иных межбюджетных трансфертов,  имеющих целевое назначение,  определяются в порядке,  установленном финансовым органом,  осуществляющим составление и организацию исполнения бюджета,  из которого предоставляются указанные межбюджетные субсидии,  субвенции и иные межбюджетные трансферты,  имеющие целевое назначение,  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 09.04.2009 № 58-ФЗ,  от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\nПеречень и коды целевых статей расходов бюджетов государственных внебюджетных фондов Российской Федерации,  территориальных государственных внебюджетных фондов устанавливаются соответственно Министерством финансов Российской Федерации,  финансовым органом субъекта Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n5. Код вида расходов включает группу,  подгруппу и элемент вида расходов. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n6. Едиными для бюджетов бюджетной системы Российской Федерации группами и подгруппами видов расходов являются:\n\n1)  группа \"Расходы на выплаты персоналу в целях обеспечения выполнения функций государственными (муниципальными)  органами,  казенными учреждениями,  органами управления государственными внебюджетными фондами\":\n\nподгруппа \"Расходы на выплаты персоналу казенных учреждений\";\n\nподгруппа \"Расходы на выплаты персоналу государственных (муниципальных)  органов\";\n\nподгруппа \"Расходы на выплаты персоналу в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Расходы на выплаты персоналу государственных внебюджетных фондов\";\n\n2)  группа \"Закупка товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Разработка,  закупка и ремонт вооружений,  военной и специальной техники,  продукции производственно-технического назначения и имущества\";\n\nподгруппа \"Закупка товаров,  работ и услуг для обеспечения специальным топливом и горюче-смазочными материалами,  продовольственного и вещевого обеспечения органов в сфере национальной безопасности,  правоохранительной деятельности и обороны\";\n\nподгруппа \"Закупка товаров,  работ и услуг в целях формирования государственного материального резерва\";\n\nподгруппа \"Иные закупки товаров,  работ и услуг для обеспечения государственных (муниципальных)  нужд\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\n3)  группа \"Социальное обеспечение и иные выплаты населению\":\n\nподгруппа \"Публичные нормативные социальные выплаты гражданам\";\n\nподгруппа \"Социальные выплаты гражданам,  кроме публичных нормативных социальных выплат\";\n\nподгруппа \"Публичные нормативные выплаты гражданам несоциального характера\";\n\nподгруппа \"Стипендии\";\n\nподгруппа \"Премии и гранты\";\n\nподгруппа \"Иные выплаты населению\";\n\n4)  группа \"Капитальные вложения в объекты государственной (муниципальной)  собственности\": (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции\";\n\nподгруппа \"Субсидии бюджетным и автономным учреждениям,  государственным (муниципальным)  унитарным предприятиям на осуществление капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность\"; (В редакции Федерального закона от 28.12.2013 № 418-ФЗ)\n\nподгруппа \"Бюджетные инвестиции иным юридическим лицам\";\n\n5)  группа \"Межбюджетные трансферты\":\n\nподгруппа \"Дотации\";\n\nподгруппа \"Субсидии\";\n\nподгруппа \"Субвенции\";\n\nподгруппа \"Иные межбюджетные трансферты\";\n\nабзац; (Утратил силу - Федеральный закон от 14.07.2022 № 264-ФЗ)\n\nподгруппа \"Межбюджетные трансферты бюджету Федерального фонда обязательного медицинского страхования\";\n\nподгруппа \"Межбюджетные трансферты бюджету Фонда пенсионного и социального страхования Российской Федерации\"; (В редакции  Федерального закона от 14.07.2022 № 264-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\n6)  группа \"Предоставление субсидий бюджетным,  автономным учреждениям и иным некоммерческим организациям\":\n\nподгруппа \"Субсидии бюджетным учреждениям\";\n\nподгруппа \"Субсидии автономным учреждениям\";\n\nподгруппа \"Субсидии некоммерческим организациям (за исключением государственных (муниципальных)  учреждений,  государственных корпораций (компаний) ,  публично-правовых компаний) \"; (В редакции Федерального закона от 26.07.2019 № 199-ФЗ)\n\n7)  группа \"Обслуживание государственного (муниципального)  долга\":\n\nподгруппа \"Обслуживание государственного долга Российской Федерации\";\n\nподгруппа \"Обслуживание государственного долга субъекта Российской Федерации\";\n\nподгруппа \"Обслуживание муниципального долга\";\n\n8)  группа \"Иные бюджетные ассигнования\":\n\nподгруппа \"Субсидии юридическим лицам (кроме некоммерческих организаций) ,  индивидуальным предпринимателям,  физическим лицам - производителям товаров,  работ,  услуг\";\n\nподгруппа \"Субсидии государственным корпорациям (компаниям) ,  публично-правовым компаниям\"; (В редакции Федерального закона от 18.07.2017 № 178-ФЗ)\n\nподгруппа \"Исполнение судебных актов\";\n\nподгруппа \"Исполнение государственных (муниципальных)  гарантий без права регрессного требования гаранта к принципалу или уступки гаранту прав требования бенефициара к принципалу\";\n\nподгруппа \"Уплата налогов,  сборов и иных платежей\";\n\nподгруппа \"Предоставление платежей,  взносов,  безвозмездных перечислений субъектам международного права\";\n\nподгруппа \"Резервные средства\";\n\nподгруппа \"Специальные расходы\";\n\nподгруппа \"Субсидии юридическим лицам,  индивидуальным предпринимателям,  являющимся стороной концессионных соглашений,  соглашений о государственно-частном партнерстве,  муниципально-частном партнерстве,  а также на финансовое обеспечение (возмещение)  затрат,  связанных с финансовой арендой (лизингом) \". (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n7. Перечень единых для бюджетов бюджетной системы Российской Федерации элементов видов расходов классификации расходов бюджетов устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 07.05.2013 № 104-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n8. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня кодов элементов видов расходов классификации расходов бюджетов при дополнительной детализации расходов бюджетов субъектов Российской Федерации (местных бюджетов)  с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n9. Внесение изменений в нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в абзацах четвертом - шестом пункта 4 настоящей статьи,  осуществляется в связи с внесением изменений в сводную бюджетную роспись федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации и применяется к отношениям,  возникшим с момента внесения изменений в сводную бюджетную роспись соответствующего бюджета. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23. Классификация источников финансирования дефицитов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2891f6070baecb0ec4a18768898c741fe39b5c6316045620521e0f6b514cd9df"},{"code_id":"BK_RF","article_number":"23.1","version_date":"1998-07-31","article_text":"1. Код классификации операций сектора государственного управления включает группу,  статью и подстатью классификации операций сектора государственного управления. (В редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n2. Едиными для бюджетов бюджетной системы Российской Федерации группами классификации операций сектора государственного управления являются:\n\n1)  доходы;\n\n2)  расходы;\n\n3)  поступление нефинансовых активов;\n\n4)  выбытие нефинансовых активов;\n\n5)  поступление финансовых активов;\n\n6)  выбытие финансовых активов;\n\n7)  увеличение обязательств;\n\n8)  уменьшение обязательств.\n\n(Пункт в редакции Федерального закона от 07.05.2013 № 104-ФЗ)\n\n3. Единый для бюджетов бюджетной системы Российской Федерации перечень статей и подстатей классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n4. Порядок применения классификации операций сектора государственного управления устанавливается Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n5. Министерство финансов Российской Федерации утверждает общие требования к порядку формирования перечня подстатей классификации операций сектора государственного управления при дополнительной детализации операций сектора государственного управления с учетом положений пунктов 3 и 4 статьи 18 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 23.1. Классификация операций сектора государственного управления","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d80d3e75f0c784ba964477ef632b25515267d8efc54419812192dd02111bbd37"},{"code_id":"BK_RF","article_number":"24","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 24.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"25","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 25.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"26","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 26.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"27","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 27.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"28","version_date":"1998-07-31","article_text":"Бюджетная система Российской Федерации основана на принципах:\n\nединства бюджетной системы Российской Федерации;\n\nразграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсамостоятельности бюджетов;\n\nравенства бюджетных прав субъектов Российской Федерации,  муниципальных образований; (Дополнение абзацем - Федеральный закон от 20.08.2004 № 120-ФЗ)\n\nполноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nсбалансированности бюджета;\n\nэффективности использования бюджетных средств; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\nобщего (совокупного)  покрытия расходов бюджетов;\n\nпрозрачности (открытости) ; (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nучастия граждан в бюджетном процессе; (Дополнение абзацем - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\nдостоверности бюджета;\n\nадресности и целевого характера бюджетных средств;\n\nподведомственности расходов бюджетов; (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)\n\nединства кассы. (Дополнение абзацем - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 28. Перечень принципов бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d1576b05a5d73b00a6cfb31520b9d27483b5f7ae80026a88ae712246d1c695e7"},{"code_id":"BK_RF","article_number":"29","version_date":"1998-07-31","article_text":"Принцип единства бюджетной системы Российской Федерации означает единство бюджетного законодательства Российской Федерации,  принципов организации и функционирования бюджетной системы Российской Федерации,  форм бюджетной документации и бюджетной отчетности,  бюджетной классификации Российской Федерации,  бюджетных мер принуждения за нарушение бюджетного законодательства Российской Федерации,  единый порядок установления и исполнения расходных обязательств,  формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  ведения бюджетного учета и составления бюджетной отчетности бюджетов бюджетной системы Российской Федерации и казенных учреждений,  единство порядка исполнения судебных актов по обращению взыскания на средства бюджетов бюджетной системы Российской Федерации. (В редакции  федеральных законов от 27.12.2005 № 197-ФЗ,  от 26.04.2007 № 63-ФЗ,  от 08.05.2010 № 83-ФЗ,  от 23.07.2013 № 252-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 29. Принцип единства бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2424db99b59ebe914b7230fab81f7f92abf0f0a294864e7544d058958194f09"},{"code_id":"BK_RF","article_number":"3","version_date":"1998-07-31","article_text":"1. Президент Российской Федерации издает указы,  регулирующие бюджетные правоотношения,  указанные в пункте 1 статьи 1 настоящего Кодекса. Указы Президента Российской Федерации не могут противоречить настоящему Кодексу и федеральным законам,  указанным в статье 2 настоящего Кодекса.\n\n2. На основании и во исполнение настоящего Кодекса,  федеральных законов,  указанных в статье 2 настоящего Кодекса,  указов Президента Российской Федерации,  предусмотренных пунктом 1 настоящей статьи,  Правительство Российской Федерации принимает нормативные правовые акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса.\n\n21. Совет Федерации Федерального Собрания Российской Федерации,  Государственная Дума Федерального Собрания Российской Федерации принимают акты,  регулирующие бюджетные правоотношения,  в случаях,  предусмотренных настоящим Кодексом. (Дополнение пунктом - Федеральный закон от 29.11.2021 № 384-ФЗ)\n\n3. Федеральные органы исполнительной власти принимают акты,  регулирующие бюджетные правоотношения,  предусмотренные статьей 1 настоящего Кодекса,  в случаях и пределах,  которые предусмотрены настоящим Кодексом,  федеральными законами,  указанными в статье 2 настоящего Кодекса,  и актами,  указанными в пунктах 1 и 2 настоящей статьи.\n\n4. Органы государственной власти субъектов Российской Федерации принимают нормативные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n5. Органы местного самоуправления принимают муниципальные правовые акты,  регулирующие бюджетные правоотношения,  в пределах своей компетенции в соответствии с настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 3. Нормативные правовые акты,  регулирующие бюджетные правоотношения","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4ff108cd5f3cc567b4eda41fe9e2e24bca90d8efd4983b08ea5af4456863169e"},{"code_id":"BK_RF","article_number":"30","version_date":"1998-07-31","article_text":"Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации означает закрепление в соответствии с законодательством Российской Федерации доходов,  расходов и источников финансирования дефицитов бюджетов за бюджетами бюджетной системы Российской Федерации,  а также определение полномочий органов государственной власти (органов местного самоуправления)  и органов управления государственными внебюджетными фондами по формированию доходов бюджетов,  источников финансирования дефицитов бюджетов и установлению и исполнению расходных обязательств публично-правовых образований.\n\nОрганы государственной власти (органы местного самоуправления)  и органы управления государственными внебюджетными фондами не вправе налагать на юридические и физические лица не предусмотренные законодательством Российской Федерации финансовые и иные обязательства по обеспечению выполнения своих полномочий.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 30. Принцип разграничения доходов,  расходов и источников финансирования дефицитов бюджетов между бюджетами бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"773b42ae70b5fd45755d6690b0630b8d599d96131e8e24b03ef1598a957574a1"},{"code_id":"BK_RF","article_number":"31","version_date":"1998-07-31","article_text":"Принцип самостоятельности бюджетов означает:\n\nправо и обязанность органов государственной власти и органов местного самоуправления самостоятельно обеспечивать сбалансированность соответствующих бюджетов и эффективность использования бюджетных средств;\n\nправо и обязанность органов государственной власти и органов местного самоуправления самостоятельно осуществлять бюджетный процесс,  за исключением случаев,  предусмотренных настоящим Кодексом;\n\nправо органов государственной власти и органов местного самоуправления устанавливать в соответствии с законодательством Российской Федерации о налогах и сборах налоги и сборы,  доходы от которых подлежат зачислению в соответствующие бюджеты бюджетной системы Российской Федерации;\n\nправо органов государственной власти и органов местного самоуправления в соответствии с настоящим Кодексом самостоятельно определять формы и направления расходования средств бюджетов (за исключением расходов,  финансовое обеспечение которых осуществляется за счет межбюджетных субсидий и субвенций из других бюджетов бюджетной системы Российской Федерации) ;\n\nнедопустимость установления расходных обязательств,  подлежащих исполнению за счет доходов и источников финансирования дефицитов других бюджетов бюджетной системы Российской Федерации,  а также расходных обязательств,  подлежащих исполнению одновременно за счет средств двух и более бюджетов бюджетной системы Российской Федерации,  за счет средств консолидированных бюджетов или без определения бюджета,  за счет средств которого должно осуществляться исполнение соответствующих расходных обязательств;\n\nправо органов государственной власти и органов местного самоуправления предоставлять средства из бюджета на исполнение расходных обязательств,  устанавливаемых иными органами государственной власти и органами местного самоуправления,  исключительно в форме межбюджетных трансфертов;\n\nнедопустимость введения в действие в течение текущего финансового года органами государственной власти и органами местного самоуправления изменений бюджетного законодательства Российской Федерации и (или)  законодательства о налогах и сборах,  законодательства о других обязательных платежах,  приводящих к увеличению расходов и (или)  снижению доходов других бюджетов бюджетной системы Российской Федерации без внесения изменений в законы (решения)  о соответствующих бюджетах,  предусматривающих компенсацию увеличения расходов,  снижения доходов;\n\nнедопустимость изъятия дополнительных доходов,  экономии по расходам бюджетов,  полученных в результате эффективного исполнения бюджетов.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 31. Принцип самостоятельности бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8874802fabf7ca02043f3d17048e9a79ea3da832eb9f375284c2cae138685d18"},{"code_id":"BK_RF","article_number":"31.1","version_date":"1998-07-31","article_text":"Принцип равенства бюджетных прав субъектов Российской Федерации,  муниципальных образований означает определение бюджетных полномочий органов государственной власти субъектов Российской Федерации и органов местного самоуправления,  установление и исполнение расходных обязательств,  формирование налоговых и неналоговых доходов бюджетов субъектов Российской Федерации и местных бюджетов,  определение объема,  форм и порядка предоставления межбюджетных трансфертов в соответствии с едиными принципами и требованиями,  установленными настоящим Кодексом.\n\nДоговоры и соглашения между органами государственной власти Российской Федерации и органами государственной власти субъектов Российской Федерации,  органами государственной власти и органами местного самоуправления,  не соответствующие настоящему Кодексу,  являются недействительными.\n\n(Дополнение статьей - Федеральный закон от 20.08.2004 № 120-ФЗ)  (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 31.1. Принцип равенства бюджетных прав субъектов Российской Федерации,  муниципальных образований","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2e02abfe93b41b2e936df7f0d2943c741646edf78fe8b19479627e8e6af6ec82"},{"code_id":"BK_RF","article_number":"32","version_date":"1998-07-31","article_text":"Принцип полноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов означает,  что все доходы,  расходы и источники финансирования дефицитов бюджетов в обязательном порядке и в полном объеме отражаются в соответствующих бюджетах.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 32. Принцип полноты отражения доходов,  расходов и источников финансирования дефицитов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c9dcb57efa0a6b4872e958378a98c0ef05f02c8e09a699d88cd4163d462eab01"},{"code_id":"BK_RF","article_number":"33","version_date":"1998-07-31","article_text":"Принцип сбалансированности бюджета означает,  что объем предусмотренных бюджетом расходов должен соответствовать суммарному объему доходов бюджета и поступлений источников финансирования его дефицита,  уменьшенных на суммы выплат из бюджета,  связанных с источниками финансирования дефицита бюджета и изменением остатков на счетах по учету средств бюджетов. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nПри составлении,  утверждении и исполнении бюджета уполномоченные органы должны исходить из необходимости минимизации размера дефицита бюджета.","article_title":"Статья 33. Принцип сбалансированности бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87c13c143a288a6f515adbb28c8f81cf267b62901675bc7ebc5d279a3fa10a58"},{"code_id":"BK_RF","article_number":"34","version_date":"1998-07-31","article_text":"(Наименование в редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)\n\nПринцип эффективности использования бюджетных средств означает,  что при составлении и исполнении бюджетов участники бюджетного процесса в рамках установленных им бюджетных полномочий должны исходить из необходимости достижения заданных результатов с использованием наименьшего объема средств (экономности)  и (или)  достижения наилучшего результата с использованием определенного бюджетом объема средств (результативности) . (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 07.05.2013 № 104-ФЗ)","article_title":"Статья 34. Принцип эффективности использования бюджетных средств","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff1f4cb01689ddfa58c11079840a1f8fb88d0e9c4e7e4b76219b8d690e7de644"},{"code_id":"BK_RF","article_number":"35","version_date":"1998-07-31","article_text":"Принцип общего (совокупного)  покрытия расходов бюджетов означает,  что расходы бюджета не могут быть увязаны с определенными доходами бюджета и источниками финансирования дефицита бюджета,  если иное не предусмотрено законом (решением)  о бюджете в части,  касающейся:\n\nсубвенций и субсидий,  полученных из других бюджетов бюджетной системы Российской Федерации;\n\nсредств целевых иностранных кредитов,  бюджетных кредитов из федерального бюджета бюджету субъекта Российской Федерации на финансовое обеспечение реализации инфраструктурных проектов и бюджетных кредитов,  указанных в пункте 1 статьи 939 настоящего Кодекса; (В редакции  федеральных законов от 02.08.2019 № 278-ФЗ,  от 28.06.2021 № 228-ФЗ,  от 26.12.2024 № 488-ФЗ)\n\nдобровольных взносов,  пожертвований,  а также средств самообложения граждан,  инициативных платежей,  предусмотренных статьями 56 и 561 Федерального закона от 6 октября 2003 года № 131-ФЗ \"Об общих принципах организации местного самоуправления в Российской Федерации\" (далее соответственно - средства самообложения граждан,  инициативные платежи) ; (В редакции Федерального закона от 20.07.2020 № 216-ФЗ)\n\nрасходов бюджета,  осуществляемых в соответствии с международными договорами (соглашениями)  с участием Российской Федерации;\n\nрасходов бюджета,  осуществляемых за пределами территории Российской Федерации;\n\nотдельных видов неналоговых доходов,  предлагаемых к введению (отражению в бюджете)  начиная с очередного финансового года;\n\nрасходов бюджета,  осуществляемых в случаях и в пределах поступления отдельных видов неналоговых доходов. (Дополнение абзацем - Федеральный закон от 25.12.2012 № 268-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 35. Принцип общего (совокупного)  покрытия расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8d7f422dd2648221cad067a8284ccbafb902c35d3cc49f23d79105fb2f2d89ff"},{"code_id":"BK_RF","article_number":"36","version_date":"1998-07-31","article_text":"Принцип прозрачности (открытости)  означает:\n\nобязательное опубликование в средствах массовой информации утвержденных бюджетов и отчетов об их исполнении,  полноту представления информации о ходе исполнения бюджетов,  а также доступность иных сведений о бюджетах по решению законодательных (представительных)  органов государственной власти,  представительных органов муниципальных образований;\n\nобязательную открытость для общества и средств массовой информации проектов бюджетов,  внесенных в законодательные (представительные)  органы государственной власти (представительные органы муниципальных образований) ,  процедур рассмотрения и принятия решений по проектам бюджетов,  в том числе по вопросам,  вызывающим разногласия либо внутри законодательного (представительного)  органа государственной власти (представительного органа муниципального образования) ,  либо между законодательным (представительным)  органом государственной власти (представительным органом муниципального образования)  и исполнительным органом государственной власти (местной администрацией) ;\n\nобеспечение доступа к информации,  размещенной в информационно-телекоммуникационной сети \"Интернет\" на едином портале бюджетной системы Российской Федерации; (Дополнение абзацем - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\nстабильность и (или)  преемственность бюджетной классификации Российской Федерации,  а также обеспечение сопоставимости показателей бюджета отчетного,  текущего и очередного финансового года (очередного финансового года и планового периода) .\n\nСекретные статьи могут утверждаться только в составе федерального бюджета.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 36. Принцип прозрачности (открытости)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f36b62f72870e8a9e1019f7d69e9a5db6e43b5e40d639023b5aa975599c9ff3"},{"code_id":"BK_RF","article_number":"37","version_date":"1998-07-31","article_text":"Принцип достоверности бюджета означает надежность показателей прогноза социально-экономического развития соответствующей территории и реалистичность расчета доходов и расходов бюджета.","article_title":"Статья 37. Принцип достоверности бюджета","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d34e50a098dfac797d327235197cbf6c680e527623f24940ef72709ac582e665"},{"code_id":"BK_RF","article_number":"38","version_date":"1998-07-31","article_text":"Принцип адресности и целевого характера бюджетных средств означает,  что бюджетные ассигнования и лимиты бюджетных обязательств доводятся до конкретных получателей бюджетных средств с указанием цели их использования.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 38. Принцип адресности и целевого характера бюджетных средств","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f1242ac60e41de85fc9281cfeb475efbab30c04bbf83366cd30e157e28dee233"},{"code_id":"BK_RF","article_number":"38.1","version_date":"1998-07-31","article_text":"Принцип подведомственности расходов бюджетов означает,  что получатели бюджетных средств вправе получать бюджетные ассигнования и лимиты бюджетных обязательств только от главного распорядителя (распорядителя)  бюджетных средств,  в ведении которого они находятся.\n\nГлавные распорядители (распорядители)  бюджетных средств не вправе распределять бюджетные ассигнования и лимиты бюджетных обязательств распорядителям и получателям бюджетных средств,  не включенным в перечень подведомственных им распорядителей и получателей бюджетных средств в соответствии со статьей 158 настоящего Кодекса.\n\nРаспорядитель и получатель бюджетных средств могут быть включены в перечень подведомственных распорядителей и получателей бюджетных средств только одного главного распорядителя бюджетных средств.\n\nПодведомственность получателя бюджетных средств главному распорядителю (распорядителю)  бюджетных средств возникает в силу закона,  нормативного правового акта Президента Российской Федерации,   Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации. (В редакции  федеральных законов от 30.12.2008 № 310-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 38.1. Принцип подведомственности расходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2816e0d2d9ebeb437f499e64d8071dd94ed3417eddcb07edc24c0eab7e89f2c"},{"code_id":"BK_RF","article_number":"38.2","version_date":"1998-07-31","article_text":"Принцип единства кассы означает зачисление всех поступлений в бюджет на единый счет бюджета и осуществление всех перечислений из бюджета с единого счета бюджета,  за исключением операций по исполнению бюджетов,  осуществляемых за пределами территории Российской Федерации в соответствии с нормативными правовыми актами Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 26.04.2007 № 63-ФЗ)  (В редакции Федерального закона от 27.12.2019 № 479-ФЗ)","article_title":"Статья 38.2. Принцип единства кассы","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a686743581f9b02ad2239e84e0aeda2ebc76dd89e4673966c095e3b86c0a5f8"},{"code_id":"BK_RF","article_number":"39","version_date":"1998-07-31","article_text":"Доходы бюджетов формируются в соответствии с бюджетным законодательством Российской Федерации,  законодательством о налогах и сборах и законодательством об иных обязательных платежах.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 39. Формирование доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d7aba55bae6cc326dac0efa48ffd570613291bf1074a39b13de6ccc1ca64979"},{"code_id":"BK_RF","article_number":"4","version_date":"1998-07-31","article_text":"1. Если международным договором Российской Федерации установлены иные правила,  чем те,  которые предусмотрены бюджетным законодательством Российской Федерации,  применяются правила международного договора.\n\n2. Международные договоры Российской Федерации применяются к бюджетным правоотношениям,  указанным в статье 1 настоящего Кодекса,  непосредственно,  за исключением случаев,  когда из международных договоров следует,  что для их применения требуется издание внутригосударственных актов.","article_title":"Статья 4. Бюджетное законодательство Российской Федерации и нормы международного права","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d599d803633bb233ae89e62575983b057cc5bfffe5c16d0a3aed0de3e7b55a82"},{"code_id":"BK_RF","article_number":"40","version_date":"1998-07-31","article_text":"1. Доходы от федеральных налогов и сборов,  региональных налогов,  местных налогов и сборов,  страховых взносов на обязательное социальное страхование,  иных обязательных платежей,  других поступлений,  являющихся источниками форм\n\nнкта,  осуществляется в связи с принятием федеральных законов и (или)  нормативных правовых актов  Правительства  Российской Федерации,  обусловливающих установление новых источников финансирования дефицитов бюджетов,  а также в связи с внесением изменений в сводную бюджетную роспись по источникам финансирования дефицита федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации. Указанные изменения в связи с внесением изменений в сводную бюджетную роспись по источникам финансирования дефицита федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации применяются с момента внесения изменений в сводную бюджетную роспись. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n6. Финансовый орган субъекта Российской Федерации утверждает перечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы государственной власти субъектов Российской Федерации,  органы управления территориальными государственными внебюджетными фондами и (или)  находящиеся в их ведении казенные учреждения. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n7. Финансовый орган муниципального образования утверждает перечень кодов видов источников финансирования дефицитов бюджетов,  главными администраторами которых являются органы местного самоуправления и (или)  находящиеся в их ведении казенные учреждения. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 40. Зачисление доходов в бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"13d1005d9becd35ce91e74c26c179269dbd638ad2b26ae33df8b55884edd7a6b"},{"code_id":"BK_RF","article_number":"40.1","version_date":"1998-07-31","article_text":"1. Излишне уплаченный (взысканный)  платеж в бюджет подлежит возврату по заявлению плательщика платежей в бюджет или подразделения судебных приставов территориального органа Федеральной службы судебных приставов (центрального аппарата Федеральной службы судебных приставов) ,  на исполнении в котором находилось исполнительное производство о взыскании платежей в бюджет,  в течение 30 календарных дней со дня регистрации такого заявления администратором доходов бюджета,  осуществляющим бюджетные полномочия по принятию решения о возврате излишне уплаченных (взысканных)  платежей в бюджет,  если иное не предусмотрено законодательными актами Российской Федерации. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n2. Заявление о возврате излишне уплаченного (взысканного)  платежа в бюджет может быть подано плательщиком платежей в бюджет или подразделением судебных приставов территориального органа Федеральной службы судебных приставов (центрального аппарата Федеральной службы судебных приставов) ,  на исполнении в котором находилось исполнительное производство о взыскании платежей в бюджет,  в течение трех лет со дня уплаты (взыскания)  такого платежа,  если иное не предусмотрено законодательными актами Российской Федерации. (В редакции  Федерального закона от 04.08.2023 № 416-ФЗ)\n\n21. В случае отмены или изменения судебного акта,  акта органа или должностного лица,  на основании которых был выдан исполнительный документ,  отмены или признания недействительным исполнительного документа заявление о возврате излишне уплаченного (взысканного)  платежа в бюджет может быть подано плательщиком платежей в бюджет в течение трех лет со дня отмены или изменения судебного акта,  акта органа или должностного лица,  на основании которых был выдан исполнительный документ,  отмены или признания недействительным исполнительного документа. (Дополнение пунктом - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n3. Возврат излишне уплаченных (взысканных)  платежей в бюджет осуществляется в соответствии с общими требованиями,  установленными Министерством финансов Российской Федерации.\n\n4. Положения настоящей статьи не распространяются на платежи,  предусмотренные законодательством о налогах и сборах,  законодательством Российской Федерации об обязательном социальном страховании от несчастных случаев на производстве и профессиональных заболеваний,  правом Евразийского экономического союза и законодательством Российской Федерации о таможенном регулировании,  а также на безвозмездные поступления. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n5. Возврат излишне уплаченных (взысканных)  платежей в бюджет в рамках исполнения денежных обязательств перед публично-правовыми образованиями осуществляется в соответствии с договорами и (или)  гражданским законодательством Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 01.07.2021 № 244-ФЗ)","article_title":"Статья 40.1. Возврат излишне уплаченных (взысканных)  платежей в бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"55c60c071418beb90353a426f624f3894eee176e4ebb66a7d867dfe89596231b"},{"code_id":"BK_RF","article_number":"41","version_date":"1998-07-31","article_text":"1. К доходам бюджетов относятся налоговые доходы,  неналоговые доходы и безвозмездные поступления.\n\n2. К налоговым доходам бюджетов относятся доходы от предусмотренных законодательством Российской Федерации о налогах и сборах федеральных налогов и сборов,  в том числе от налогов,  предусмотренных специальными налоговыми режимами,  региональных налогов,  местных налогов и сборов,  а также пеней и штрафов по ним. (В редакции Федерального закона от 03.11.2015 № 301-ФЗ)\n\n3. К неналоговым доходам бюджетов относятся:\n\nдоходы от использования имущества,  находящегося в государственной или муниципальной собственности,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nдоходы от продажи имущества (кроме акций и иных форм участия в капитале,  государственных запасов драгоценных металлов и драгоценных камней) ,  находящегося в государственной или муниципальной собственности,  за исключением движимого имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 28.12.2013 № 418-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nдоходы от платных услуг,  оказываемых казенными учреждениями; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nсредства,  полученные в результате применения мер гражданско-правовой,  административной и уголовной ответственности,  в том числе штрафы,  конфискации,  компенсации,  а также средства,  полученные в возмещение вреда,  причиненного Российской Федерации,  субъектам Российской Федерации,  муниципальным образованиям,  и иные суммы принудительного изъятия;\n\nсредства самообложения граждан,  инициативные платежи; (В редакции Федерального закона от 20.07.2020 № 216-ФЗ)\n\nиные неналоговые доходы.\n\n4. К безвозмездным поступлениям относятся:\n\nдотации из других бюджетов бюджетной системы Российской Федерации;\n\nсубсидии из других бюджетов бюджетной системы Российской Федерации (межбюджетные субсидии) ;\n\nсубвенции из федерального бюджета и (или)  из бюджетов субъектов Российской Федерации;\n\nиные межбюджетные трансферты из других бюджетов бюджетной системы Российской Федерации;\n\nбезвозмездные поступления от физических и юридических лиц,  международных организаций и правительств иностранных государств,  в том числе добровольные пожертвования.\n\n5. Доходы от использования имущества,  находящегося в государственной или муниципальной собственности,  и платных услуг,  оказываемых казенными учреждениями,  средства безвозмездных поступлений и иной приносящей доход деятельности при составлении,  утверждении,  исполнении бюджета и составлении отчетности о его исполнении включаются в состав доходов бюджета. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\n6. Нормативные правовые акты,  муниципальные правовые акты,  договоры,  в соответствии с которыми уплачиваются платежи,  являющиеся источниками неналоговых доходов бюджетов,  должны предусматривать положения о порядке их исчисления,  размерах,  сроках и (или)  об условиях их уплаты. (Дополнение пунктом - Федеральный закон от 22.10.2014 № 311-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 41. Виды доходов бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdd1b3740382bcc3d6fbb3966536b7be5e6d180a16ac6db2feb8ab250b2567f4"},{"code_id":"BK_RF","article_number":"42","version_date":"1998-07-31","article_text":"К доходам бюджетов от использования имущества,  находящегося в государственной или муниципальной собственности,  относятся:\n\nдоходы,  получаемые в виде арендной либо иной платы за передачу в возмездное пользование государственного и муниципального имущества,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\"; (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\nсредства,  получаемые в виде процентов по остаткам бюджетных средств на счетах в Центральном банке Российской Федерации и в кредитных организациях;\n\nсредства,  получаемые от передачи имущества,  находящегося в государственной или муниципальной собственности (за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  и имущества,  переданного в доверительное управление юридическим лицам,  созданным в организационно-правовой форме государственной компании) ,  в залог,  в доверительное управление; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nплата за пользование бюджетными кредитами;\n\nдоходы в виде прибыли,  приходящейся на доли в уставных (складочных)  капиталах хозяйственных товариществ и обществ,  или дивидендов по акциям,  принадлежащим Российской Федерации,  субъектам Российской Федерации или муниципальным образованиям,  за исключением случаев,  установленных федеральными законами; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nчасть прибыли государственных и муниципальных унитарных предприятий,  остающаяся после уплаты налогов и иных обязательных платежей;\n\nдругие предусмотренные законодательством Российской Федерации доходы от использования имущества,  находящегося в государственной или муниципальной собственности,  за исключением имущества бюджетных и автономных учреждений,  а также имущества государственных и муниципальных унитарных предприятий,  в том числе казенных,  земельных участков и иных объектов недвижимого имущества,  находящихся в федеральной собственности,  используемых единым институтом развития в жилищной сфере в соответствии с Федеральным законом от 24 июля 2008 года № 161-ФЗ \"О содействии развитию жилищного строительства\". (В редакции федеральных законов от 08.05.2010 № 83-ФЗ; от 24.11.2014 № 375-ФЗ; от 03.07.2016 № 345-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 42. Доходы от использования имущества,  находящегося в государственной или муниципальной собственности","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"58b3e5b97b4aa273ddc7615ccda223279ba39e85d23ea32036c78288cf6894a8"},{"code_id":"BK_RF","article_number":"43","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 43.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"44","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 44.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"45","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 45.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"}]$law7d0011$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
